class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        max_r = 0
        for _, r in queries:
            if r > max_r:
                max_r = r

        # powers[i] = 4^i. Ensure there is a power strictly greater than max_r.
        powers = [1]
        while powers[-1] <= max_r:
            powers.append(powers[-1] * 4)

        def prefix(n: int) -> int:
            """Return sum_{x=1}^n f(x), where f(x) is divisions by 4 needed to reach 0."""
            if n <= 0:
                return 0

            total = 0
            # For block i (0-based), f(x) = i + 1 on [4^i, 4^(i+1) - 1].
            for i in range(len(powers) - 1):
                start = powers[i]
                if start > n:
                    break

                end = powers[i + 1] - 1
                if end > n:
                    end = n

                total += (i + 1) * (end - start + 1)

            return total

        ans = 0
        for l, r in queries:
            steps = prefix(r) - prefix(l - 1)
            ans += (steps + 1) // 2

        return ans

from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        limit = k - 1

        def tri(t: int) -> int:
            if t < 0:
                return 0
            return (t + 1) * (t + 2) // 2

        def count_pairs(a: int, b: int) -> int:
            # Count x in [0, a-1], y in [0, b-1] with x + y <= limit.
            return (
                tri(limit)
                - tri(limit - a)
                - tri(limit - b)
                + tri(limit - a - b)
            )

        # Minimum contributions: assign each subarray to its rightmost minimum.
        prev_less = [-1] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] >= x:
                stack.pop()
            if stack:
                prev_less[i] = stack[-1]
            stack.append(i)

        next_le = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while stack and nums[stack[-1]] > x:
                stack.pop()
            if stack:
                next_le[i] = stack[-1]
            stack.append(i)

        ans = 0
        for i, x in enumerate(nums):
            left_choices = i - prev_less[i]
            right_choices = next_le[i] - i
            ans += x * count_pairs(left_choices, right_choices)

        # Maximum contributions: assign each subarray to its rightmost maximum.
        prev_greater = [-1] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] <= x:
                stack.pop()
            if stack:
                prev_greater[i] = stack[-1]
            stack.append(i)

        next_ge = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while stack and nums[stack[-1]] < x:
                stack.pop()
            if stack:
                next_ge[i] = stack[-1]
            stack.append(i)

        for i, x in enumerate(nums):
            left_choices = i - prev_greater[i]
            right_choices = next_ge[i] - i
            ans += x * count_pairs(left_choices, right_choices)

        return ans

