from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if abs(k) > total:
            return -1

        offset = total
        target = k + offset

        # Positive-product DP: zero-free subsequences with product 1..limit.
        # dp0[prod] / dp1[prod] are bitsets of reachable alternating sums
        # for even / odd subsequence length.
        dp0 = [0] * (limit + 1)
        dp1 = [0] * (limit + 1)
        active = []  # (parity, product) states with nonzero bitset

        # all0/all1: all non-empty subsequences, regardless of product.
        # zero0/zero1: non-empty subsequences that contain at least one zero.
        all0 = 0
        all1 = 0
        zero0 = 0
        zero1 = 0

        for x in nums:
            old_all0 = all0
            old_all1 = all1
            old_zero0 = zero0
            old_zero1 = zero1

            if x == 0:
                # Append zero to all old subsequences: parity toggles, sum unchanged.
                if old_all0:
                    all1 |= old_all0
                if old_all1:
                    all0 |= old_all1

                singleton = 1 << offset  # sum 0, odd length
                all1 |= singleton

                # Appending zero makes product zero for every old subsequence.
                if old_all0:
                    zero1 |= old_all0
                if old_all1:
                    zero0 |= old_all1
                zero1 |= singleton

            else:
                # Update all-subsequence DP.
                if old_all0:
                    all1 |= old_all0 << x
                if old_all1:
                    all0 |= old_all1 >> x
                all1 |= 1 << (offset + x)

                # Update zero-product DP by appending positive x to old zero states.
                if old_zero0:
                    zero1 |= old_zero0 << x
                if old_zero1:
                    zero0 |= old_zero1 >> x

                # Update positive-product DP only when product can remain <= limit.
                if x <= limit:
                    if active:
                        snapshot = []
                        for p, prod in active:
                            bits = dp0[prod] if p == 0 else dp1[prod]
                            if bits:
                                snapshot.append((p, prod, bits))

                        for p, prod, bits in snapshot:
                            nprod = prod * x
                            if nprod > limit:
                                continue

                            if p == 0:
                                shifted = bits << x
                                if shifted:
                                    if dp1[nprod] == 0:
                                        active.append((1, nprod))
                                    dp1[nprod] |= shifted
                            else:
                                shifted = bits >> x
                                if shifted:
                                    if dp0[nprod] == 0:
                                        active.append((0, nprod))
                                    dp0[nprod] |= shifted

                    # Start a new positive-product subsequence with x.
                    bit = 1 << (offset + x)
                    if dp1[x] == 0:
                        active.append((1, x))
                    dp1[x] |= bit

        # Prefer positive products; zero is only used if no positive product works.
        for prod in range(limit, 0, -1):
            if dp0[prod] and ((dp0[prod] >> target) & 1):
                return prod
            if dp1[prod] and ((dp1[prod] >> target) & 1):
                return prod

        if ((zero0 >> target) & 1) or ((zero1 >> target) & 1):
            return 0

        return -1

import sys

MOD = 998244353
INV2 = (MOD + 1) // 2


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    s = data[1].strip()
    if len(s) > N:
        s = s[:N]

    # Relations on {0,1} are stored as 4-bit masks.
    # bit 0: 0->0, bit 1: 0->1, bit 2: 1->0, bit 3: 1->1.
    # comp[r][t] = r followed by t.
    comp = [[0] * 16 for _ in range(16)]
    for r in range(16):
        for t in range(16):
            res = 0
            if r & 1:  # 0->0
                if t & 1:
                    res |= 1
                if t & 2:
                    res |= 2
            if r & 2:  # 0->1
                if t & 4:
                    res |= 1
                if t & 8:
                    res |= 2
            if r & 4:  # 1->0
                if t & 1:
                    res |= 4
                if t & 2:
                    res |= 8
            if r & 8:  # 1->1
                if t & 4:
                    res |= 4
                if t & 8:
                    res |= 8
            comp[r][t] = res

    # Transition relation for one vertex, indexed by d_i.
    # s_i = 0: d=0,1,2 only.
    T0 = [2, 9, 4, 0]
    # s_i = 1: d=0,1,2,3.
    T1 = [2, 11, 13, 4]
    T = (T0, T1)
    allowed = ((0, 1, 2), (0, 1, 2, 3))

    # Swap states 0 <-> 1.
    swap = [0] * 16
    for r in range(16):
        swap[r] = ((r & 1) << 3) | ((r & 2) << 1) | ((r & 4) >> 1) | ((r & 8) >> 3)

    canon = [r if r < swap[r] else swap[r] for r in range(16)]

    # Live orbits under state-swap symmetry, excluding the empty relation.
    start = 9  # identity relation: 0->0 and 1->1
    start_c = canon[start]
    seen = {start_c}
    stack = [start_c]

    while stack:
        c = stack.pop()
        members = (c,) if swap[c] == c else (c, swap[c])
        for b in (0, 1):
            for d in allowed[b]:
                for r in members:
                    r2 = comp[r][T[b][d]]
                    if r2:
                        nc = canon[r2]
                        if nc not in seen:
                            seen.add(nc)
                            stack.append(nc)

    reps = sorted(seen)
    oid = {c: i for i, c in enumerate(reps)}
    S = len(reps)
    init = oid[start_c]

    # Orbit sizes and final acceptance weights.
    inv_sizes = [0] * S
    weights = [0] * S
    for i, c in enumerate(reps):
        if swap[c] == c:
            members = (c,)
            inv = 1
        else:
            members = (c, swap[c])
            inv = INV2
        inv_sizes[i] = inv

        acc = 0
        for r in members:
            if (r & 1) or (r & 8):  # has (0,0) or (1,1)
                acc += 1
        weights[i] = acc * inv % MOD

    # One-step aggregated transitions.
    # For an orbit, transition multiplicity is averaged over its members.
    single_edges = [[], []]
    for b in (0, 1):
        edges = []
        for src, c in enumerate(reps):
            if swap[c] == c:
                members = (c,)
                inv = 1
            else:
                members = (c, swap[c])
                inv = INV2

            counts = [0] * S
            for r in members:
                for d in allowed[b]:
                    r2 = comp[r][T[b][d]]
                    if r2:
                        counts[oid[canon[r2]]] += 1

            for dst, val in enumerate(counts):
                if val:
                    coeff = val * inv % MOD
                    if coeff:
                        edges.append((src, dst, coeff))

        single_edges[b] = tuple(edges)

    # Precompute transitions for all 10-bit blocks of s.
    B = 10
    block_edges = [()] * (1 << B)
    se = single_edges
    mod = MOD

    for p in range(1 << B):
        edges = []
        for src in range(S):
            vec = [0] * S
            vec[src] = 1

            # Input blocks are built most-significant-bit first.
            for pos in range(B - 1, -1, -1):
                b = (p >> pos) & 1
                new = [0] * S
                for sr, dst, m in se[b]:
                    vs = vec[sr]
                    if vs:
                        new[dst] = (new[dst] + vs * m) % mod
                vec = new

            for dst, val in enumerate(vec):
                if val:
                    edges.append((src, dst, val))

        block_edges[p] = tuple(edges)

    # Process the string in 10-bit blocks.
    dp = [0] * S
    dp[init] = 1

    idx = 0
    cnt = 0
    be = block_edges

    for ch in s:
        idx = (idx << 1) | (ch & 1)
        cnt += 1
        if cnt == B:
            ndp = [0] * S
            for sr, dst, m in be[idx]:
                ndp[dst] += dp[sr] * m
            dp = [x % mod for x in ndp]
            idx = 0
            cnt = 0

    # Remaining fewer than B characters.
    if cnt:
        for ch in s[-cnt:]:
            edges = se[1] if (ch & 1) else se[0]
            ndp = [0] * S
            for sr, dst, m in edges:
                ndp[dst] += dp[sr] * m
            dp = [x % mod for x in ndp]

    ans = 0
    for val, w in zip(dp, weights):
        ans = (ans + val * w) % mod

    print(ans)


