                    for i in range(1, m):
                        append(bcoord(-1 - i, -1))
                    append(bcoord(-m, -2))
                    for x in range(-m + 1, 1):
                        append(bcoord(x, -2))
                else:
                    m = B // 2
                    append(bcoord(-1, 0))
                    for i in range(1, m):
                        append(bcoord(-1 - i, 0))
                    append(bcoord(-m, -1))
                    for x in range(-m + 1, 0):
                        append(bcoord(x, -1))

            append(f"R {OFF} {OFF + 1}")

            if R >= 4:
                H = R // 2 - 1
                for r in range(OFF + 1, OFF + H + 1):
                    append(f"R {r} {OFF + 1}")
                append(f"R {OFF + H} {OFF}")
                for r in range(OFF + H - 1, OFF, -1):
                    append(f"R {r} {OFF}")

    if out:
        sys.stdout.write("\n".join(out) + "\n")

