import sys
from collections import deque

INF = 10**30


def solve_positions(x, s):
    """
    x: sorted positions of 1s in A
    s: sorted positions of 1s in B
    Returns minimum operations, or -1.
    """
    K = len(x)
    L = len(s)

    if K < L:
        return -1
    if K == 0:
        return 0 if L == 0 else -1
    if L == 0:
        return -1

    # Total gap reduction needed.
    S = (x[-1] - x[0]) - (s[-1] - s[0])
    if S < 0:
        return -1

    # Required displacement of the leftmost piece.
    delta = s[0] - x[0]
    parity = S & 1

    # If there is only one target square, there are no target gaps to match.
    if L == 1:
        ans = INF
        for u in (0, 1):
            v = u ^ parity
            cost = delta + u
            other = S + v - delta
            if other > cost:
                cost = other
            if cost < ans:
                ans = cost
        return ans

    Lm1 = L - 1
    r0 = 0  # next target gap index for start b0 = 0
    r1 = 0  # next target gap index for start b0 = 1
    p = 0   # parity of x[j] - x[0]
    s0 = s[0]

    # Greedily match target gaps to initial gaps for both possible b0 values.
    for j in range(K - 1):
        d = x[j + 1] - x[j]

        if r0 < Lm1:
            g = s[r0 + 1] - s[r0]
            if d >= g:
                if d > g:
                    r0 += 1
                else:
                    q = (s[r0] - s0) & 1
                    if (p ^ q) == 0:
                        r0 += 1

        if r1 < Lm1:
            g = s[r1 + 1] - s[r1]
            if d >= g:
                if d > g:
                    r1 += 1
                else:
                    q = (s[r1] - s0) & 1
                    if (p ^ q) == 1:
                        r1 += 1

        p ^= (d & 1)

        if r0 == Lm1 and r1 == Lm1:
            break

    ans = INF

    if r0 == Lm1:
        # b0 = 0, b_last = parity
        v = parity
        cost = delta
        other = S + v - delta
        if other > cost:
            cost = other
        ans = cost

    if r1 == Lm1:
        # b0 = 1, b_last = 1 ^ parity
        v = 1 ^ parity
        cost = delta + 1
        other = S + v - delta
        if other > cost:
            cost = other
        if cost < ans:
            ans = cost

    return -1 if ans == INF else ans


def validate(max_n=6):
    """
    Brute-force validation on all nonempty subsets for small N.
    Run with: python3 solution.py --validate
    """
    for N in range(1, max_n + 1):
        masks = list(range(1, 1 << N))
        pos = {
            m: tuple(i for i in range(N) if (m >> i) & 1)
            for m in masks
        }

        trans = {}
        for m in masks:
            st = pos[m]
            arr = []
            for c in range(N):
                ns = sorted({
                    p + (1 if c > p else (-1 if c < p else 0))
                    for p in st
                })
                nm = 0
                for p in ns:
                    nm |= 1 << p
                arr.append(nm)
            trans[m] = arr

        for start in masks:
            dist = {start: 0}
            q = deque([start])
            while q:
                cur = q.popleft()
                nd = dist[cur] + 1
                for nxt in trans[cur]:
                    if nxt not in dist:
                        dist[nxt] = nd
                        q.append(nxt)

            for target in masks:
                if target.bit_count() <= start.bit_count():
                    expected = solve_positions(pos[start], pos[target])
                    actual = dist.get(target, -1)
                    if expected != actual:
                        print(
                            f"MISMATCH N={N} start={start} target={target} "
                            f"expected={expected} actual={actual}"
                        )
                        return False

    print("validation ok")
    return True


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        validate()
        return

    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        a = data[idx]
        idx += 1
        b = data[idx]
        idx += 1

        x = [i for i, c in enumerate(a) if c == 49]  # ord('1') == 49
        s = [i for i, c in enumerate(b) if c == 49]

        out.append(str(solve_positions(x, s)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "--validate":
        validate()
    else:
        main()

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        left, middle, right = p.split('*')

        def occurrences(text: str, pattern: str):
            """
            Returns all start indices where pattern occurs in text, in sorted order.
            Uses KMP for linear time. Empty patterns return an empty list because
            empty fragments are handled separately by the caller.
            """
            m = len(pattern)
            n = len(text)
            if m == 0 or m > n:
                return []

            # KMP prefix function.
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pattern[i] != pattern[j]:
                    j = pi[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                pi[i] = j

            # KMP search.
            occ = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pattern[j]:
                    j = pi[j - 1]
                if ch == pattern[j]:
                    j += 1
                    if j == m:
                        occ.append(i - m + 1)
                        j = pi[j - 1]
            return occ

        occ_left = occurrences(s, left) if left else []
        occ_mid = occurrences(s, middle) if middle else []
        occ_right = occurrences(s, right) if right else []

        # p == "**"
        if not left and not middle and not right:
            return 0

        # Every non-empty literal fragment must occur at least once.
        if left and not occ_left:
            return -1
        if middle and not occ_mid:
            return -1
        if right and not occ_right:
            return -1

        left_len = len(left)
        mid_len = len(middle)
        right_len = len(right)

        INF = 10**18
        ans = INF

        # Case 1: middle is empty, so we only need left before right.
        if not middle:
            if not left:
                return right_len if right else 0
            if not right:
                return left_len if left else 0

            i = 0
            latest_left = -1

            # Sweep right occurrences and keep the latest left occurrence
            # whose end is <= current right start.
            for start_right in occ_right:
                while i < len(occ_left) and occ_left[i] + left_len <= start_right:
                    latest_left = occ_left[i]
                    i += 1

                if latest_left != -1:
                    length = start_right + right_len - latest_left
                    if length < ans:
                        ans = length

            return ans if ans != INF else -1

        # Case 2: middle is non-empty.
        # If both sides are empty, the shortest match is exactly one middle occurrence.
        if not left and not right:
            return mid_len

        i_left = 0
        latest_left = -1
        i_right = 0

        len_occ_left = len(occ_left)
        len_occ_right = len(occ_right)

        # Sweep middle occurrences in increasing start order.
        for start_mid in occ_mid:
            if left:
                # Latest left occurrence ending at or before this middle start.
                while i_left < len_occ_left and occ_left[i_left] + left_len <= start_mid:
                    latest_left = occ_left[i_left]
                    i_left += 1

                if latest_left == -1:
                    continue

                start = latest_left
            else:
                # Leading star can be trimmed away in an optimal substring.
                start = start_mid

            threshold = start_mid + mid_len

            if right:
                # Earliest right occurrence starting at or after this middle end.
                while i_right < len_occ_right and occ_right[i_right] < threshold:
                    i_right += 1

                # Middle starts only increase, so no later middle can match right either.
                if i_right == len_occ_right:
                    break

                end = occ_right[i_right] + right_len
            else:
                # Trailing star can be trimmed away in an optimal substring.
                end = threshold

            length = end - start
            if length < ans:
                ans = length

        return ans if ans != INF else -1

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1

        # KMP prefix function for str2.
        s2 = [ord(ch) - 97 for ch in str2]
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j and s2[i] != s2[j]:
                j = pi[j - 1]
            if s2[i] == s2[j]:
                j += 1
            pi[i] = j

        # Build KMP automaton states 0..m.
        # State m means the last m characters are exactly str2.
        trans = []
        row0 = [0] * 26
        row0[s2[0]] = 1
        trans.append(row0)

        for state in range(1, m):
            row = trans[pi[state - 1]].copy()
            row[s2[state]] = state + 1
            trans.append(row)

        # From accepting state m, fallback before consuming the next character.
        trans.append(trans[pi[m - 1]].copy())

        # Bit masks for automaton states.
        bits = [1 << i for i in range(m + 1)]
        m_bit = bits[m]
        full_mask = (1 << (m + 1)) - 1
        non_m_mask = full_mask ^ m_bit

        trans_bits = []
        tm_pairs = []       # (all next-state mask, current-state bit)
        tmn_pairs = []      # (non-m next-state mask, current-state bit)
        reach_m_mask = 0
        full_no_mask = 0
        full_F_mask = 0

        for s, row in enumerate(trans):
            rb = [bits[ns] for ns in row]
            trans_bits.append(rb)

            mask = 0
            for b in rb:
                mask |= b

            if mask:
                tm_pairs.append((mask, bits[s]))
                full_no_mask |= bits[s]

            no_m = mask & non_m_mask
            if no_m:
                tmn_pairs.append((no_m, bits[s]))
                full_F_mask |= bits[s]

            if mask & m_bit:
                reach_m_mask |= bits[s]

        is_t = [ch == 'T' for ch in str1]

        # masks[p] = bitmask of automaton states before position p
        # from which suffix p..L-1 can be completed.
        masks = [0] * (L + 1)
        masks[L] = full_mask
        m1 = m - 1

        # Cache repeated feasibility transitions.
        cache_no = {full_mask: full_no_mask, 0: 0}
        cache_f = {full_mask: full_F_mask, 0: 0}

        # Positions that end a length-m window.
        for p in range(L - 1, m1 - 1, -1):
            next_mask = masks[p + 1]

            if is_t[p - m1]:
                if not (next_mask & m_bit):
                    return ""
                if reach_m_mask == 0:
                    return ""
                masks[p] = reach_m_mask
            else:
                res = cache_f.get(next_mask)
                if res is None:
                    cur = 0
                    for mask, bit in tmn_pairs:
                        if mask & next_mask:
                            cur |= bit
                    res = cur
                    cache_f[next_mask] = res

                if res == 0:
                    return ""
                masks[p] = res

        # Prefix positions before the first full window.
        for p in range(m1 - 1, -1, -1):
            next_mask = masks[p + 1]

            res = cache_no.get(next_mask)
            if res is None:
                cur = 0
                for mask, bit in tm_pairs:
                    if mask & next_mask:
                        cur |= bit
                res = cur
                cache_no[next_mask] = res

            if res == 0:
                return ""
            masks[p] = res

        if not (masks[0] & 1):
            return ""

        # Greedily construct the lexicographically smallest feasible string.
        ans = []
        state = 0
        letters = [chr(97 + i) for i in range(26)]

        for p in range(L):
            next_mask = masks[p + 1]
            rb = trans_bits[state]
            row = trans[state]

            if p < m1:
                for c in range(26):
                    if next_mask & rb[c]:
                        ans.append(letters[c])
                        state = row[c]
                        break
                else:
                    return ""

            elif is_t[p - m1]:
                if not (next_mask & m_bit):
                    return ""
                for c in range(26):
                    if rb[c] == m_bit:
                        ans.append(letters[c])
                        state = m
                        break
                else:
                    return ""

            else:
                for c in range(26):
                    if rb[c] != m_bit and (next_mask & rb[c]):
                        ans.append(letters[c])
                        state = row[c]
                        break
                else:
                    return ""

        return ''.join(ans)

from typing import List
from math import gcd

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        if not nums:
            return 0

        vals = sorted(set(target))
        m = len(vals)
        if m == 0:
            return 0

        size = 1 << m
        full = size - 1
        INF = 10**18
        max_val = max(nums)
        cap = max_val + INF + 1

        lcms = [1] * size
        for mask in range(1, size):
            lb = mask & -mask
            bit = lb.bit_length() - 1
            prev = mask ^ lb
            l = lcms[prev]
            if l >= cap:
                lcms[mask] = cap
            else:
                t = vals[bit]
                val = (l // gcd(l, t)) * t
                lcms[mask] = cap if val > cap else val

        submasks = [[] for _ in range(size)]
        for mask in range(size):
            rem = full ^ mask
            sub = rem
            while sub:
                submasks[mask].append(sub)
                sub = (sub - 1) & rem

        dp = [INF] * size
        dp[0] = 0

        for x in nums:
            costs = [0] * size
            for mask in range(1, size):
                l = lcms[mask]
                c = (l - x % l) % l
                if c > INF:
                    c = INF
                costs[mask] = c

            for mask in range(full, -1, -1):
                base = dp[mask]
                if base >= INF:
                    continue
                for sub in submasks[mask]:
                    c = costs[sub]
                    if c >= INF:
                        continue
                    val = base + c
                    nm = mask | sub
                    if val < dp[nm]:
                        dp[nm] = val
                        if nm == full and val == 0:
                            return 0

        return dp[full]

import sys
from collections import deque

def solve() -> None:
    input = sys.stdin.buffer.readline
    N, M = map(int, input().split())

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * N

    active_odd = 0      # odd-sized connected components with at least one edge
    isolated = 0        # components of size 1
    both_odd_even = 0   # even-sized components whose two color classes are both odd

    for s in range(N):
        if color[s] != -1:
            continue

        color[s] = 0
        q = deque([s])
        cnt = [1, 0]
        deg_sum = 0

        while q:
            u = q.popleft()
            deg_sum += len(adj[u])
            cu = color[u]
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = cu ^ 1
                    cnt[color[v]] += 1
                    q.append(v)

        size = cnt[0] + cnt[1]

        if size == 1:
            isolated += 1
        elif size % 2 == 1:
            active_odd += 1
        else:
            if (cnt[0] & 1) and (cnt[1] & 1):
                both_odd_even += 1

    if N % 2 == 1:
        first_wins = (M % 2 == 1)
    else:
        if active_odd >= 3:
            first_wins = (M % 2 == 1)
        elif active_odd >= 1:
            first_wins = True
        else:
            first_wins = ((M + both_odd_even + isolated // 2) % 2 == 1)

    print("Aoki" if first_wins else "Takahashi")

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        small = set()
        large = 0

        for x in nums:
            if x <= threshold:
                small.add(x)
            else:
                large += 1

        if not small:
            return large

        # If 1 is present, every small value is connected to it.
        # If there is only one distinct small value, it forms one component.
        if 1 in small or len(small) == 1:
            return large + 1

        T = threshold
        T1 = T + 1
        half = T // 2

        parent = list(range(T1))
        size = [1] * T1

        def find(a: int) -> int:
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        # For each present value x <= threshold, union it with all multiples
        # of x up to threshold. Two values are connected iff they share a
        # common multiple <= threshold, equivalent to lcm <= threshold.
        for x in small:
            if x > half:
                continue

            rx = find(x)
            for m in range(x + x, T1, x):
                rm = find(m)
                if rx != rm:
                    if size[rx] < size[rm]:
                        rx, rm = rm, rx
                    parent[rm] = rx
                    size[rx] += size[rm]

        return large + len({find(x) for x in small})
